#define KQ_LAYER_FIXTURE_ONLY
#include "layer_test.c"

static uint32_t bits(float v){uint32_t b;memcpy(&b,&v,sizeof(b));return b;}
int main(int argc,char **argv){static const kq_layer_family families[3]={KQ_LAYER_FAMILY_GDN,KQ_LAYER_FAMILY_QSA,KQ_LAYER_FAMILY_PLE_GDN};uint32_t f,i;int holdout=argc==2&&strcmp(argv[1],"--holdout")==0;if(argc>2||(argc==2&&!holdout))return 2;for(f=0;f<3;++f){fixture x;float input[128],output[128];uint32_t ids[4]={11,22,33,44};uint64_t scratch_bytes=0;void *scratch;kq_diagnostic d;kq_status s;if(!setup(&x,families[f]))return 2;for(i=0;i<128;++i){input[i]=(float)((int)(i%19)-9)*0.03125f;if(holdout)input[i]+=(float)((int)(i%17)-8)*0.0001f;}if(kq_layer_required_scratch_bytes(x.layer,x.state,4,&scratch_bytes,&d)!=KQ_STATUS_OK)return 2;scratch=calloc(1,(size_t)scratch_bytes);if(!scratch)return 2;s=kq_layer_prefill_f32(x.layer,&x.weights,input,families[f]==KQ_LAYER_FAMILY_PLE_GDN?ids:NULL,4,NULL,output,128,x.state,scratch,scratch_bytes,NULL,NULL,NULL,&d);if(s!=KQ_STATUS_OK){fprintf(stderr,"%s: %s\n",kq_status_string(s),d.message);return 2;}printf("FAMILY %s 128",kq_layer_family_name(families[f]));for(i=0;i<128;++i)printf(" %08x",bits(output[i]));printf("\nSTATE position=%llu owned=%llu scratch=%llu\n",(unsigned long long)kq_layer_state_position(x.state),(unsigned long long)kq_layer_state_owned_bytes(x.state),(unsigned long long)scratch_bytes);free(scratch);teardown(&x);}return 0;}
